"""Random limits for FizzBuzz: a single number.

One of the four always reaches a multiple of fifteen, because a run that stops
at fourteen would let the mistake this problem is really about -- checking
three before checking fifteen -- go unnoticed.
"""


def generate(rng, count):
    builders = (_small, _reaches_fifteen, _medium, _longer)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, n, description=""):
    return {"name": name, "stdin": "%d\n" % n, "description": description}


def _small(rng, index):
    n = rng.randint(2, 6)
    return _case("counts to %d" % n, n)


def _reaches_fifteen(rng, index):
    n = 15 * rng.randint(1, 3) + rng.randint(0, 2)
    return _case("past a multiple of fifteen #%d" % index, n,
                 "This run reaches a number divisible by both 3 and 5, which "
                 "must print FizzBuzz rather than Fizz.")


def _medium(rng, index):
    n = rng.randint(7, 14)
    return _case("counts to %d" % n, n)


def _longer(rng, index):
    return _case("a longer run #%d" % index, rng.randint(20, 45))
